import os
from functools import wraps

from taf.gnb.oam.coam.cu.utilities.logger import log_warning


DEPRECATION_MESSAGE = (
    "Use of {keyword_name} is deprecated and will be removed in the future."
    " Please use {substitute} instead."
)

def deprecated(substitute):
    """This is a decorator which can be used to mark functions as deprecated.
    It will result in a warning being logged when the function is used."""

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            disable_logging = os.getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
            if not disable_logging:
                log_warning(DEPRECATION_MESSAGE.format(keyword_name=func.__name__, substitute=substitute))
            return func(*args, **kwargs)
        return wrapper

    return decorator
